        trigger: "Um oponente conjura uma magia que tem a mantícora como alvo e exige uma salvaguarda.",
        description: "A mantícora ganha +4 de bônus de circunstância na salvaguarda. Se obtiver sucesso crítico na salvaguarda, pode escolher uma criatura a até 9 m que não era alvo original da magia. Essa criatura se torna um novo alvo da magia e deve tentar a própria salvaguarda contra a mesma CD.",
