        description: "A mantícora couraçada flexiona os músculos sob as escamas para obter proteção temporária melhor. A mantícora ganha +2 de bônus de circunstância à CA e resistência 15 ao dano de concussão, perfurante ou cortante, à escolha dela. Esses benefícios duram até o início do próximo turno da mantícora ou até ela usar Ajustar Escamas de novo.",
