        description: "O guardião florescente pode desfazer-se por um instante numa nuvem rodopiante de pétalas e pólen para passar por sarças e esgueirar-se por fendas. Ao Distanciar em terreno florestal, o guardião florescente ignora terreno difícil e pode atravessar obstáculos desde que haja uma passagem estreita.",
