        trigger: "Uma criatura Monta ou usa Comandar um Animal enquanto cavalga esta criatura.",
        description: "Salvaguarda de Reflexos CD 36.\nQuem disparou precisa passar num teste de Reflexos contra a CD listada ou cai da montaria e fica Caído. Em falha crítica, também sofre 1d6 de concussão além do dano normal da queda. A maioria das montarias só usa esta reação contra um cavaleiro de confiança se estiver assustada ou maltratada.",
