        description: "O guardião florescente Distancia duas vezes e faz um Golpe de galhada depois de qualquer um dos Distanciar. Se o Golpe acertar, o guardião florescente causa 2d12 extra de dano de concussão, e o alvo sofre penalidade de circunstância de –2 na próxima salvaguarda de Fortitude contra Sifão Brotante.",
