        actionType: "one",
        description: "A toupeira cabeça-dura deixa um buraco de toca no próprio quadrado ou num quadrado adjacente. O quadrado se torna terreno difícil, mas pode ser aplainado de volta a terreno normal com uma ação de Interagir.",
