        description: "Sempre que um membro é decepado, ele precisa tentar um teste simples CD 5. Em um sucesso, o membro começa a se transformar lentamente numa nova estrela-da-terra mamute ao longo de uma semana, a menos que seja banhado em ácido ou fogo.",
