        description: "O guia espiritual gasta 10 minutos para formar um vínculo com uma criatura mortal. Enquanto o vínculo existir, o guia espiritual aumenta os PV atuais e máximos em 14, ganha +2 de bônus de status nas jogadas de ataque e de dano, e pode se comunicar telepaticamente com o mortal vinculado enquanto os dois estiverem no mesmo plano. O guia espiritual só pode estar vinculado a um mortal por vez, e pode usar esta ação de novo para encerrar o vínculo ou para formar um novo (o que também encerra o antigo). O vínculo também termina se o guia espiritual ou o mortal morrer.\nEste vínculo reforça a conexão do guia espiritual com o Universo. Enquanto estiver vinculado, o guia espiritual perde os traços incorpóreo e espírito, perde a imunidade a doença, paralisia e veneno, bem como a resistência a todo dano, e passa a causar com os Golpes a quantidade apropriada de dano físico (em geral perfurante ou cortante) em vez de dano de força.",
