        description: "A hidra tem regeneração igual a 3 × o número de cabeças que possui. Se o corpo da hidra estiver sem alguma cabeça e os cotos restantes não tiverem sido cauterizados, a hidra tenta uma salvaguarda de Fortitude CD 39 depois de recuperar PV da regeneração. Em um sucesso, um coto não cauterizado regenera duas cabeças; em um sucesso crítico, dois cotos não cauterizados regeneram duas cabeças cada. A hidra nunca pode ter mais do que o dobro do número de cabeças que possui normalmente. A regeneração da hidra só se desativa por completo se todas as cabeças forem decepadas e todos os cotos cauterizados; nesse ponto, ela morre.",
