        description: "O basilisco real cospe o veneno com força imensa, causando 5d10 de ácido e 5d8 de perfurante (salvaguarda básica de Reflexos CD 32) a criaturas numa @Template[line|distance:240] e expondo cada criatura que sofreu dano ao veneno de basilisco real. A linha penetra barreiras com Solidez menor que 20, ignorando quaisquer bônus que elas concederiam por cobertura. O basilisco real não pode usar Cuspe Talhador de Pedra de novo por [[/gmr 1d4 #Recarregar Cuspe Talhador de Pedra]]{1d4 rodadas}.",
