        description: "Embora um shotalashu não possa falar, nem mesmo telepaticamente, compreende comandos simples nos idiomas que conhece. Devolve sensações telepáticas de emoção a criaturas que o toquem ou ao parceiro do vínculo telepático a qualquer distância.",
