        description: "O shotalashu caça cravando a mente nos inimigos. Uma criatura a até 9 m precisa tentar uma salvaguarda de Vontade CD 18.\nSucesso crítico: A criatura não é afetada.\nSucesso: A criatura sofre −1,5 m de penalidade de status aos Deslocamentos por uma rodada.\nFalha: A criatura sofre −3 m de penalidade de status aos Deslocamentos por uma rodada. O shotalashu pode então Saltar.\nFalha crítica: A criatura fica Desprotegido e Imobilizado por uma rodada. O shotalashu pode Saltar.",
