    abilities: [
      {
        id: "stargut-hydra-skymetal-metamorphosis",
        name: "Metamorfose de Metal Celeste",
        originalName: "Skymetal Metamorphosis",
        actionType: "passive",
        description: "Cada hidra estrelar tem pelo menos uma metamorfose resultante de consumir um metal celeste específico e internalizar suas propriedades. Se você der a uma hidra estrelar mais de uma metamorfose, deve considerar aumentar o nível dela e alterar as estatísticas.\nAdamantina: os Golpes da hidra estrelar ignoram Solidez e são tratados como adamantina. A hidra estrelar ganha resistência 10 a dano físico (exceto adamantina).\nAbísio (aura, veneno): a hidra estrelar emite uma aura de radiação nauseante do abísio no corpo. Qualquer criatura que comece o turno a até 9 m da hidra estrelar fica Enjoado 1.\nDjezet (mágico): a hidra estrelar ganha +2 de bônus de status em salvaguardas contra magia.\nInubrix: os Golpes da hidra estrelar ignoram resistência a dano dos efeitos de especialização de armadura de armaduras de metal e não disparam a reação Bloqueio com Escudo nem reações de runas de propriedade de armadura.\nNoqual: os Golpes e as habilidades da hidra estrelar ganham +2 de bônus de status ao dano contra criaturas com a habilidade de Conjurar uma Magia.\nOricalco: quando a hidra estrelar tem apenas duas cabeças restantes, fica Acelerado. Só pode usar a ação extra para Distanciar ou Golpear.\nSiccatita: depois que a hidra estrelar sofre dano de fogo, fica superaquecida, ganhando imunidade a fogo e fraqueza 10 a frio. Enquanto estiver superaquecida, dano de frio pode ser usado para cauterizar um coto. Depois que a hidra estrelar sofre dano de frio, fica resfriada, ganhando imunidade a frio e fraqueza 10 a fogo.",
      },
      {
        id: "stargut-hydra-all-around-vision",
        name: "Visão Panorâmica",
        originalName: "All-Around Vision",
        actionType: "passive",
        description: "A criatura vê em todas as direções ao mesmo tempo e portanto não pode ser flanqueada.",
      },
      {
        id: "stargut-hydra-hydra-regeneration",
        name: "Regeneração da Hidra",
        originalName: "Hydra Regeneration",
        actionType: "passive",
        description: "A hidra estrelar tem regeneração igual a 3 × o número de cabeças que possui. Se o corpo da hidra estiver sem alguma cabeça e os cotos restantes não tiverem sido cauterizados, a hidra tenta uma salvaguarda de Fortitude CD 29 depois de recuperar PV da regeneração. Em um sucesso, um coto não cauterizado regenera duas cabeças; em um sucesso crítico, dois cotos não cauterizados regeneram duas cabeças cada. A hidra nunca pode ter mais do que o dobro do número de cabeças que possui normalmente. A regeneração da hidra só se desativa por completo se todas as cabeças forem decepadas e todos os cotos cauterizados; nesse ponto, ela morre.",
      },
      {
        id: "stargut-hydra-head-regrowth",
        name: "Regeneração de Cabeça",
        originalName: "Head Regrowth",
        actionType: "passive",
        description: "Uma hidra estrelar normalmente tem cinco cabeças. Uma criatura pode tentar decepar uma das cabeças da hidra alvejando-a especificamente e causando dano igual aos PV da cabeça. Uma cabeça que não seja decepada por completo volta aos PV máximos no fim do turno de qualquer criatura. Uma hidra pode regenerar uma cabeça decepada usando a regeneração da hidra. Uma criatura pode impedir esse recrescimento causando dano de ácido ou de fogo ao coto, cauterizando-o. Efeitos de ácido ou fogo de alvo único precisam alvejar um coto específico, mas efeitos que causem dano de respingo ou afetem áreas que cubram o espaço inteiro da hidra cauterizam todos os cotos se causarem dano de ácido ou de fogo. Se o ataque que decepou uma cabeça causar qualquer dano de ácido ou de fogo, o coto é cauterizado na hora. Se as cinco cabeças forem cauterizadas, a hidra morre.",
      },
      {
        id: "stargut-hydra-reactive-heads",
        name: "Cabeças Reativas",
        originalName: "Reactive Heads",
        actionType: "passive",
        description: "Uma hidra estrelar ganha uma reação extra por rodada para cada cabeça além da primeira, que só pode usar para fazer Golpes Reativos. Não pode usar mais de 1 reação na mesma ação disparadora, mesmo que uma criatura saia de vários quadrados no alcance, e precisa usar uma cabeça diferente para cada Golpe Reativo que fizer. Sempre que uma das cabeças da hidra é decepada, a hidra perde 1 das reações extras por rodada.",
      },
      {
        id: "stargut-hydra-reactive-strike",
        name: "Golpe Reativo",
        originalName: "Reactive Strike",
        actionType: "reaction",
        trigger: "Uma criatura no alcance usa uma ação de manipular ou de movimento, faz um ataque à distância, ou sai de um quadrado durante uma ação de movimento que está usando.",
        description: "A criatura tenta um Golpe corpo a corpo contra quem disparou. Se o ataque for um acerto crítico e o gatilho foi uma ação de manipular, a criatura interrompe essa ação. Este Golpe não conta para a penalidade de ataques múltiplos, e essa penalidade não se aplica a este Golpe.",
      },
      {
        id: "stargut-hydra-stargut-hydra-heads",
        name: "Cabeças da Hidra Estrelar",
        originalName: "Stargut Hydra Heads",
        actionType: "passive",
        description: "PV (cabeça) 22, regeneração de cabeça. Imunidades: dano de área. Fraquezas: cortante 10.",
      },
      {
        id: "stargut-hydra-vomit-meteorites",
        name: "Vomitar Meteoritos",
        originalName: "Vomit Meteorites",
        actionType: "two",
        description: "A hidra estrelar sacode o corpo inteiro e vomita pedaços de meteorito num @Template[cone|distance:30] que causam 5d6 de concussão a todas as criaturas na área (salvaguarda básica de Reflexos CD 25). A área se torna terreno difícil por 1 minuto, embora uma criatura possa usar uma ação de Interagir para limpar um quadrado dos escombros. A hidra estrelar não pode Vomitar Meteoritos por [[/gmr 1d4 #Recarregar Vomit Meteorites]]{1d4 rodadas}.",
      },
    ],
    summary: "Hidra que come estrelas. O ventre brilha e queima.",
