        description: "O morcego pétreo exala um sopro de gás petrificante sobre uma criatura adjacente, alvejando uma parte específica do corpo. O alvo precisa passar numa salvaguarda de Fortitude CD 20 ou fica parcialmente petrificado por 1 minuto, com um efeito que varia conforme a parte alvejada.\nRosto: o rosto da criatura endurece e uma película de pedra bloqueia parcialmente a visão. Ela fica Ofuscada.\nMão: uma das mãos da criatura é petrificada. Ela não pode Soltar itens dessa mão nem usá-la para manipulação fina. Rolagens de ataque com armas seguradas nessa mão sofrem penalidade de status de –2.\nPerna: um trecho da perna da criatura fica inflexível e pesado. Ela sofre penalidade de status de –3 m no Deslocamento. Se todas as pernas da criatura forem petrificadas assim, o Deslocamento cai para 1,5 m. A critério do Mestre, uma criatura cujo movimento não dependa de pernas, como criaturas que Voam com asas, não sofre penalidade nesses outros Deslocamentos.",
