    abilities: [
      {
        id: "sunscale-serpent-constant-spells",
        name: "Magias constantes",
        originalName: "Constant Spells",
        actionType: "passive",
        description: "Uma magia constante afeta a criatura sem ela precisar conjurá-la, e a duração é ilimitada. Se a magia constante for contrariada, a criatura pode reativá-la gastando as ações de conjuração normais da magia.",
      },
      {
        id: "sunscale-serpent-reactive-strike",
        name: "Golpe Reativo (somente cauda)",
        originalName: "Reactive Strike (Tail Only)",
        actionType: "reaction",
        trigger: "Uma criatura no alcance usa uma ação de manipular ou de movimento, faz um ataque à distância, ou sai de um quadrado durante uma ação de movimento que está usando.",
        description: "A criatura tenta um Golpe corpo a corpo contra quem disparou. Se o ataque for um acerto crítico e o gatilho foi uma ação de manipular, a criatura interrompe essa ação. Este Golpe não conta para a penalidade de ataques múltiplos, e essa penalidade não se aplica a este Golpe.",
      },
      {
        id: "sunscale-serpent-bond-with-mortal",
        name: "Vínculo com Mortal",
        originalName: "Bond with Mortal",
        actionType: "passive",
        frequency: "1 vez por dia",
        description: "A serpente de escamas solares gasta 10 minutos para formar um vínculo com uma criatura mortal. Enquanto o vínculo existir, a serpente aumenta os PV atuais e máximos em 28, ganha +2 de status nas rolagens de ataque e de dano, e pode se comunicar telepaticamente com o mortal vinculado enquanto os dois estiverem no mesmo plano. A serpente só pode estar vinculada a um mortal por vez, e pode usar esta ação de novo para encerrar o vínculo ou formar um novo (o que também encerra o antigo). O vínculo também termina se a serpente ou o mortal morrer.\nEsse vínculo fortalece a conexão da serpente com o Universo. Enquanto estiver vinculada, a serpente perde os traços incorpóreo e espírito, perde a imunidade a doença, paralisia e veneno, junto com a resistência a todo dano, e muda os Golpes para causar a quantidade apropriada de dano físico (em geral perfurante ou cortante) em vez de dano de força.",
      },
      {
        id: "sunscale-serpent-bonded-strike",
        name: "Golpe Vinculado",
        originalName: "Bonded Strike",
        actionType: "two",
        requirements: "A serpente de escamas solares está vinculada a um mortal.",
        description: "A serpente de escamas solares faz um Golpe de mandíbulas. Se este ataque acertar, o mortal vinculado pode gastar a reação para Golpear o mesmo alvo.",
      },
      {
        id: "sunscale-serpent-sun-s-heat",
        name: "Calor do Sol",
        originalName: "Sun's Heat",
        actionType: "two",
        description: "A serpente de escamas solares Voa até o Deslocamento de voo. Todas as criaturas diretamente abaixo dos espaços pelos quais se move precisam passar numa salvaguarda de Fortitude CD 31 ou são expostas ao veneno Toque do Sol. A serpente não pode voar a mais de 18 m acima do alvo, ou o veneno se dispersa demais na queda para fazer efeito.",
      },
      {
        id: "sunscale-serpent-sun-s-touch",
        name: "Toque do Sol",
        originalName: "Sun's Touch",
        actionType: "passive",
        description: "Salvaguarda de Fortitude CD 34\nDuração máxima 6 rodadas\nEstágio 1 6d8 de veneno e Desajeitado 1 (1 rodada)\nEstágio 2 8d6 de veneno e Desajeitado 2 (1 rodada)\nEstágio 3 6d10 de veneno e Fatigado (1 rodada)",
      },
      {
        id: "sunscale-serpent-swallow-whole",
        name: "Engolir Inteiro",
        originalName: "Swallow Whole",
        actionType: "one",
        description: "Grande, 2d10+9 de força e 2d10 de fogo, Ruptura 32.\nA criatura tenta engolir um alvo do tamanho listado ou menor que esteja agarrado ou imobilizado nas mandíbulas ou na boca. Se o alvo engolido for do tamanho máximo listado, não pode usar Engolir Inteiro de novo. Se for menor, em geral pode engolir mais; o Mestre define o máximo. A criatura faz um teste de Atletismo contra a CD de Reflexos do alvo. Se passar, engole. A boca ou as mandíbulas deixam de agarrar quem foi engolido, então a criatura pode usá-las de novo para Golpear ou Agarrar. Não pode atacar alvos que tenha engolido.\n\nUm alvo engolido fica agarrado, Atrasado 1, e precisa prender a respiração ou começa a sufocar. Sofre o dano listado ao ser engolido e no fim de cada turno enquanto estiver engolido. Se Escapar da condição de agarrado desta habilidade, sai pela boca — isso também solta qualquer outro alvo preso na boca ou nas mandíbulas. Quem está engolido só pode atacar a criatura com ataques desarmados ou armas de Bulk leve ou menor. A criatura que engoliu fica Desprotegida contra esse ataque. Se a criatura sofrer dano perfurante ou cortante igual ou maior que o valor de Ruptura listado num único ataque ou magia, o alvo se corta para fora. Quem se solta (Escapando ou se cortando) pode respirar na hora e sai no espaço da criatura.\n\nSe a criatura morrer, um alvo engolido pode ser libertado por criaturas adjacentes ao cadáver se gastarem um total combinado de 3 ações cortando-a com arma ou ataque desarmado que cause dano perfurante ou cortante.",
      },
      {
        id: "sunscale-serpent-unleash-the-sun",
        name: "Liberar o Sol",
        originalName: "Unleash the Sun",
        actionType: "three",
        requirements: "A serpente de escamas solares está voando.",
        description: "A serpente de escamas solares Voa até o Deslocamento de voo e então despenca no chão, liberando uma onda de calor que causa 5d10 de fogo a todas as criaturas numa @Template[burst|distance:60] e queima os olhos com a glória em erupção das escamas. Cada criatura na área deve tentar uma salvaguarda de Reflexos CD 31.\nSucesso crítico A criatura não é afetada.\nSucesso A criatura sofre metade do dano.\nFalha A criatura sofre dano total e fica Ofuscada por 1 rodada.\nFalha crítica A criatura sofre dano total, fica Cega por 1 rodada e Ofuscada por 1 minuto.",
      },
      {
        id: "sunscale-serpent-improved-grab",
        name: "Agarrar Aprimorado",
        originalName: "Improved Grab",
        actionType: "free",
        description: "A criatura pode usar Agarrar como ação livre disparada por um acerto com o Golpe inicial.\n\nSe usada depois de um Golpe, a criatura tenta Agarrar o alvo usando a parte do corpo com que atacou. Esta tentativa não aplica nem conta para a penalidade de ataques múltiplos. Em vez disso, a criatura pode usar Agarrar e escolher uma criatura que já esteja agarrando ou imobilizando com um apêndice que tenha Agarrar para estender automaticamente essa condição até o fim do próximo turno da criatura.",
      },
      {
        id: "sunscale-serpent-push",
        name: "Empurrar",
        originalName: "Push",
        actionType: "one",
        requirements: "A última ação da criatura foi um Golpe bem-sucedido que lista Empurrar na entrada de dano.",
        description: "A criatura tenta Empurrar o alvo. Esta tentativa não aplica nem conta para a penalidade de ataques múltiplos. Se Empurrar listar uma distância, use essa distância no sucesso.",
      },
    ],
