    abilities: [
      {
        id: "tyrafdir-all-around-vision",
        name: "Visão em todas as direções",
        originalName: "All-Around Vision",
        actionType: "passive",
        description: "A criatura vê em todas as direções ao mesmo tempo e portanto não pode ser flanqueada.",
      },
      {
        id: "tyrafdir-hydra-regeneration",
        name: "Regeneração de Hidra",
        originalName: "Hydra Regeneration",
        actionType: "passive",
        description: "Em uma falha, o tyrafdir cresce duas cabeças ilusórias.\nA hidra tem regeneração igual a 3 × o número de cabeças. Se o corpo da hidra estiver sem alguma cabeça e os cotos restantes não tiverem sido cauterizados, a hidra tenta uma salvaguarda de Fortitude CD 31 depois de recuperar PV da regeneração. Em sucesso, um coto não cauterizado regenera duas cabeças; em sucesso crítico, dois cotos não cauterizados regeneram duas cabeças cada. A hidra nunca pode ter mais que o dobro das cabeças que tem normalmente. A regeneração da hidra só desativa por completo se todas as cabeças forem decepadas e todos os cotos cauterizados; nesse ponto ela morre.\nA criatura recupera o número listado de PV no início de cada turno. A condição Morrendo nunca passa de Morrendo 3 enquanto a regeneração estiver ativa. Porém, se sofrer dano de um tipo listado, a regeneração desliga até o fim do próximo turno. Desligue a regeneração antes de aplicar qualquer dano do tipo listado, pois esse dano pode matar a criatura ao levá-la a Morrendo 4.",
      },
      {
        id: "tyrafdir-deceptive-heads",
        name: "Cabeças Enganosas",
        originalName: "Deceptive Heads",
        actionType: "passive",
        description: "Um tyrafdir é astuto, ainda que pouco inteligente, e usa ilusões de cabeças regeneradas para confundir e atormentar os oponentes. Quando um tyrafdir falha, mas não obtém falha crítica, na salvaguarda de Fortitude para regenerar uma cabeça, uma ilusão se materializa para imitar o crescimento. Isso cria duas cabeças enganosas que funcionam de modo diferente das cabeças reais. O tyrafdir ganha um Golpe de mandíbulas enganosas enquanto tiver pelo menos uma cabeça enganosa. Qualquer criatura que ataque uma cabeça enganosa ou use a ação Procurar para examiná-la pode tentar descrer da ilusão (salvaguarda de Vontade CD 27).",
      },
      {
        id: "tyrafdir-deceptive-regrowth",
        name: "Regeneração Enganosa",
        originalName: "Deceptive Regrowth",
        actionType: "passive",
        description: "Um tyrafdir normalmente tem seis cabeças. Uma criatura pode tentar decepar uma das cabeças do tyrafdir alvejando-a especificamente e causando dano igual aos PV da cabeça. Uma cabeça que não seja decepada por completo volta ao máximo de PV no fim do turno de qualquer criatura. Um tyrafdir pode regenerar uma cabeça decepada usando Regeneração de Hidra. Uma criatura pode impedir essa regeneração causando dano de fogo ao coto, cauterizando-o. Efeitos de fogo de alvo único precisam alvejar um coto específico, mas efeitos que causam dano de respingo ou afetam áreas que cubram o espaço inteiro da hidra cauterizam todos os cotos se causarem dano de fogo. Se o ataque que decepou a cabeça causar qualquer dano de fogo ou for feito com uma arma de ferro frio, o coto é cauterizado na hora. Se as seis cabeças forem cauterizadas, a hidra morre.",
      },
      {
        id: "tyrafdir-reactive-heads",
        name: "Cabeças Reativas",
        originalName: "Reactive Heads",
        actionType: "passive",
        description: "Uma hidra ganha uma reação extra por rodada para cada cabeça além da primeira, que só pode usar para fazer Golpes Reativos. Não pode usar mais de 1 reação na mesma ação que disparou, mesmo que uma criatura saia de vários quadrados no alcance, e precisa usar uma cabeça diferente em cada Golpe Reativo. Sempre que uma das cabeças da hidra é decepada, a hidra perde 1 das reações extras por rodada.",
      },
      {
        id: "tyrafdir-reactive-strike",
        name: "Golpe Reativo",
        originalName: "Reactive Strike",
        actionType: "reaction",
        trigger: "Uma criatura no alcance usa uma ação de manipular ou de movimento, faz um ataque à distância, ou sai de um quadrado durante uma ação de movimento que está usando.",
        description: "A criatura tenta um Golpe corpo a corpo contra quem disparou. Se o ataque for um acerto crítico e o gatilho foi uma ação de manipular, a criatura interrompe essa ação. Este Golpe não conta para a penalidade de ataques múltiplos, e essa penalidade não se aplica a este Golpe.",
      },
      {
        id: "tyrafdir-tyrafdir-heads",
        name: "Cabeças de Tyrafdir",
        originalName: "Tyrafdir Heads",
        actionType: "passive",
        description: "PV (cabeça) 30, regeneração enganosa\nImunidades dano de área\nFraqueza ferro frio 10, cortante 10",
      },
      {
        id: "tyrafdir-noxious-exhalation",
        name: "Exalação Nociva",
        originalName: "Noxious Exhalation",
        actionType: "two",
        description: "O tyrafdir exala uma névoa nociva por todas as bocas, espalhando-se numa @Template[emanation|distance:20] que causa 4d10 de veneno às criaturas na área (salvaguarda básica de Reflexos CD 24). Qualquer criatura que falhe na salvaguarda deve tentar uma salvaguarda de Vontade CD 24 ou ganha fraqueza 10 a mental e penalidade de status de –1 em salvaguardas de Vontade por 24 horas. O tyrafdir não pode usar Exalação Nociva de novo por [[/gmr 1d4 #Recarregar Noxious Exhalation]]{1d4 rodadas}.",
      },
    ],
    summary: "Hidra feérica. As cabeças discordam — e mesmo assim matam.",
