        description: "As profundezas chamam o guardião, sobretudo quando se move pelo ar. Quando usa Salto em Distância, pode gastar qualquer movimento não usado do Salto em Distância para Escavar. Além disso, o guardião pode Escavar por qualquer matéria terrosa, inclusive rocha. Ao fazê-lo, move-se com o Deslocamento de escavação completo.",
