        name: "Salto Eruptivo",
        originalName: "Erupting Jump",
        actionType: "two",
        description: "O guardião puxa um jato de lava e então salta da massa que se solidifica ao esfriar. O guardião Salta até o dobro do Deslocamento. Ao aterrissar, a força do impacto causa 6d12 de concussão a todas as criaturas numa @Template[emanation|distance:15] com salvaguarda básica de Fortitude CD 42. Em falha crítica, a criatura também é empurrada 3 m para longe do guardião.",
