        actionType: "passive",
        description: "Obsidiana que esfria depressa gruda no corpo do alvo e endurece em torno dos membros. O alvo deve tentar uma salvaguarda de Reflexos CD 42. Em falha, o alvo fica Imobilizado até [[/act escape dc=42]]{Escapar}. Em falha crítica, o alvo fica Desprotegido enquanto permanecer imobilizado.",
