        name: "Correntes Descendentes da Tempestade",
        originalName: "Tempest Downdrafts",
        actionType: "free",
        trigger: "A guardiã Voa.",
        description: "As asas da guardiã geram rajadas poderosas que desviam criaturas menores do curso. Uma @Template[emanation|distance:60], centrada na guardiã, se enche de ventos atravessados por relâmpagos até o início do próximo turno da guardiã. As criaturas precisam passar numa salvaguarda de Reflexos CD 42 para usar qualquer ação de movimento nos ventos; criaturas voadoras usam o resultado um grau de sucesso pior do que o que rolarem. Criaturas que obtêm falha crítica são sopradas 9 m para longe da guardiã, caem Caídas e sofrem 4d6 de eletricidade.",
