        name: "Mudar Forma",
        originalName: "Change Shape",
        actionType: "one",
        description: "Humano Médio com punho +11 causando 1d4+6 de concussão, ou alce Grande com galhada e casco +11 causando 1d8+6 de concussão.\nA criatura muda de forma por tempo indefinido. Pode usar esta ação de novo para voltar à forma natural ou assumir outra forma. Salvo indicação em contrário, não pode usar Mudar Forma para parecer um indivíduo específico. Usar Mudar Forma conta como criar um disfarce para Personificar (Enganação). A transformação vence automaticamente as CDs de Percepção para decidir se a criatura é da ancestralidade ou do tipo em que se transformou, e ela ganha +4 de status na CD de Enganação para impedir que vejam através do disfarce. A habilidade lista as formas que pode assumir. A criatura não ganha habilidades especiais da nova forma, só o corpo: em cada forma, substitui Deslocamentos e Golpes normais, e pode mudar sentidos ou tamanho. Qualquer mudança está na ficha.",
